      "ign: left;\n}\n.link-button:hover {\n  text-decoration: underline;\n}\n\n.flash-alert {\n  background: rgba(252, 165, 165, 0.1);\n  color: var(--color-danger);\n  border: 1px solid rgba(252, 165, 165, 0.25);\n  border-radius: 8px;\n  padding: 10px 14px;\n  margin-bottom: 16px;\n  font-size: 13px;\n}\nmain p.flash-",
      "alert {\n  color: var(--color-danger);\n  font-size: 13px;\n}\n\nmain .request-id {\n  margin: 8px 0 0;\n}\nmain .read-at {\n  margin-top: 32px;\n}\n\ncode {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  font-size: 12px;\n}\ncode {\n  background: var(--color-bg-secondary);\n  border: 1px solid va",
